package com.nivor.file;
import com.nivor.file.FileDtos.*;import java.io.IOException;import java.util.List;import org.springframework.core.io.InputStreamResource;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController@RequestMapping("/api/files")public class FileController{private final FileService service;public FileController(FileService s){service=s;}@GetMapping public List<FileView> list(@AuthenticationPrincipal UserDetails u,@RequestParam(required=false)String search,@RequestParam(required=false)String category,@RequestParam(required=false)Long project){return service.list(u.getUsername(),search,category,project);}@GetMapping("/{id}")public FileView get(@AuthenticationPrincipal UserDetails u,@PathVariable long id){return service.get(u.getUsername(),id);}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public ResponseEntity<FileView> upload(@AuthenticationPrincipal UserDetails u,@RequestPart("file")MultipartFile file,@RequestParam(required=false)String category,@RequestParam(required=false)Long project)throws IOException{return ResponseEntity.status(HttpStatus.CREATED).body(service.upload(u.getUsername(),file,category,project));}@GetMapping("/{id}/download")public ResponseEntity<InputStreamResource> download(@AuthenticationPrincipal UserDetails u,@PathVariable long id)throws IOException{FileService.Download d=service.download(u.getUsername(),id);return ResponseEntity.ok().contentType(MediaType.parseMediaType(d.mimeType())).contentLength(d.size()).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(d.filename()).build().toString()).body(new InputStreamResource(d.stream()));}@DeleteMapping("/{id}")public ResponseEntity<Void> delete(@AuthenticationPrincipal UserDetails u,@PathVariable long id)throws IOException{service.delete(u.getUsername(),id);return ResponseEntity.noContent().build();}@PostMapping("/{id}/analyze")public AnalysisView analyze(@AuthenticationPrincipal UserDetails u,@PathVariable long id){return service.analyze(u.getUsername(),id);}@GetMapping("/{id}/analysis")public ResponseEntity<AnalysisView> analysis(@AuthenticationPrincipal UserDetails u,@PathVariable long id){AnalysisView view=service.analysis(u.getUsername(),id);return view==null?ResponseEntity.notFound().build():ResponseEntity.ok(view);}}
